INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madstone', 'MadStone is a puzzle game in which players must break apart blocks to help special gems (called MadStones) drop down to a pool at the bottom of the screen through their own weight and gravity. Players use the D-pad on the Wii Remote to move an onscreen cursor to select which blocks to break, and can also cause an earthquake that breaks up random blocks by shaking the Wii Remote. The game also features a versus mode against the computer or a second player in addition to the single player arcade mode.' FROM games WHERE igdb_id = 50721 ON CONFLICT (game_id, language_code) DO NOTHING;
