INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sengoku Rance: Sanbiki ga Kittari Tsuitari Moyashitari - Slash! Thrust! Burn!', 'Suzume''s past comes back to haunt Kanami as a Silver Eye Sect ninja named Kakusui steals Kanami''s Decapitation Blade and plans to get revenge on Suzume and Inukai over the death of her leader, Gumo Danjou by using its abilities to become stronger than Suzume. The chase is on, as Kanami, Suzume and Senhime work together in order to get Kanami back her Decapitation Blade.' FROM games WHERE igdb_id = 259312 ON CONFLICT (game_id, language_code) DO NOTHING;
