INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Topple', 'Topple turns the rules of puzzle-action games upside down with a beautiful, engaging and endlessly replayable tower building game. Players build wobbly and delicate towers to dizzying heights, while the expressive, hilarious and occasionally mischievous shapes are dragged and rotated with multi-touch controls as you battle gravity by tilting the tower. Unlock all the levels and game modes, challenge others via email and discover the 20 achievements as you ask: how high can you go?' FROM games WHERE igdb_id = 93973 ON CONFLICT (game_id, language_code) DO NOTHING;
