INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ookami to Koushinryou: Boku to Holo no Ichi-nen', 'A spin-off of the main story, the game takes place in an alternative world and follows the adventures of the player as an original character loosely based on the series’ protagonist Kraft Lawrence. A novice merchant seeking to expand his business, he signs a contract for ownership of a horse-drawn cart, which comes with some very unusual conditions. Accordingly, the player is tasked with the job of delivering Holo, a girl with the ears and tail of a wolf, to her hometown whose location she has forgotten.' FROM games WHERE igdb_id = 123449 ON CONFLICT (game_id, language_code) DO NOTHING;
