INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cruxata', 'Cruxata was a web MMOG based on medieval wars during the crusades, a series of intermittent military campaigns sanctioned by various Popes in the Middle Ages. The game was created by an independent game developer know with the nickname "lucky". The game was recently closed due to lack of time to maintain and update.' FROM games WHERE igdb_id = 17256 ON CONFLICT (game_id, language_code) DO NOTHING;
