INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ape-escape-m', 310347, '2008-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8kl7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sct978.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ape Escape M', 'Ape Escape M takes the core concepts of the console Ape Escape games and brings them into a 2D game with an overhead perspective. The story is similar to the original Ape Escape in that it has you playing as Spike as he tries to stop Specter and his army of apes, but it does take place after the first game. In each level, you’re tasked with capturing most of the apes with your net before you can advance. You also have other gadgets, such as the stun club, radar, and slingshot that can be used to track the apes and stun them for easier capture. As you explore each level, you can find healing items, items that grant additional lives, and enemies that can only be defeated and not captured. Some levels also have doors that lead back to hidden areas in previous levels if you can find the key to unlock them. There are 121 apes in total to catch across five different worlds and in-game achievements can also be unlocked based on the player’s accomplishments.' FROM games WHERE igdb_id = 310347 ON CONFLICT (game_id, language_code) DO NOTHING;
