INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taiko no Tatsujin 12', 'The 12th Taiko arcade machine, released in December 2008. Taiko 12 marked a plateau as far as development of the series was concerned- the game mechanics and graphics have been perfected over so many different versions. No major fixes or upgrades were made on this version, except for one small thing- instead of ''Taiko no Tatsujin Twelve'' being announced on the title screen, it was replaced with the Japanese equivalent ''Jyuu-ni'' (which also means twelve).' FROM games WHERE igdb_id = 342610 ON CONFLICT (game_id, language_code) DO NOTHING;
