INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kuukiyomi', 183651, '2008-06-02', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1s3l.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kuukiyomi', 'What if you could try out exactly how considerate to be in life? Kuukiyomi is a social puzzle game in which players try out different responses to social situations. These range from everyday moments, like making room for others on the bus or standing to one side on the escalator, to wilder and silly choices like performing in sync as a backup dancer or joining a Japanese superhero team. Each situation is presented as a fast minigame, similar to the WarioWare series, with no real explanation; players are left to themselves to judge what it is they need to do. There are 100 minigames in all, and after finishing every game players are given a personality reading based on their performance in various categories such as "social appropriateness" or "reaction speed". After finishing the game once, players unlock the ability to replay any of the stages individually and an endurance competition with three of the different minigames where players have to see how many times they can complete it in a row.' FROM games WHERE igdb_id = 183651 ON CONFLICT (game_id, language_code) DO NOTHING;
