INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Otomedius Gorgeous!', 'Otomedius Gorgeous is the Xbox 360 port of Otomedius Arcade, a side scrolling shooter by Konami which featured personification of space fighters from various Konami games like Gradius, Xexex, Salamander and Parodius. The name is a pun, being a portmanteau of the terms "otome" (meaning "maiden" in Japanese) and "Gradius". It was released for the Japanese Xbox 360 in November 20, 2008.' FROM games WHERE igdb_id = 23037 ON CONFLICT (game_id, language_code) DO NOTHING;
