INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '8bit Killer', '8bit killer is an action first person shooter styled to resemble a NES game in look and feel. 32x32 pixel textures, 64 color nes palette and 1bit sounds make this game look like an early 90s game. The soundtrack has been created by the genius RushJet1. The story, characters and scenes are inspired by films like Mad Max or 2013: Rescue in LA and by games like Contra, Megaman, Bionic Commando, Metroid, Catacomb 3D or the sequel Wolfenstein 3D, and many others...' FROM games WHERE igdb_id = 65522 ON CONFLICT (game_id, language_code) DO NOTHING;
