INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luntik Learns Numbers', 'Curious Luntik invites girls and boys to fun counting lessons! Together with Luntik, other characters from the cartoon “Moon Guest” will find themselves at the epicenter of incredible events: the grasshopper Kuzya, the worm Korney Korneich and two hooligans - the caterpillars Pupsen and Vupsen. Favorite characters will challenge your child to complete a series of fun tasks to demonstrate their knowledge of numbers. If the baby fails to pass the test, he will have another, simpler one.' FROM games WHERE igdb_id = 268369 ON CONFLICT (game_id, language_code) DO NOTHING;
