INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Christmas with Weezer', 'Christmas With Weezer is a cheerful music beat game from the makers of Tap Tap Revenge, featuring exclusive holiday songs performed by everyone''s favorite rock band, Weezer. Tap your way into the holiday season to six familiar songs with an upbeat rock & roll twist. Additionally, get to hard mode to play two hit tracks from Weezer''s Red Album. This game is sure to make even the grinch crack a smile.' FROM games WHERE igdb_id = 70426 ON CONFLICT (game_id, language_code) DO NOTHING;
