INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FloodSim', 'Floodsim is a flash-based serious game created by Norwich Union in cooperation with Playgen in 2008 in order to raise awareness of the dangers that flooding present to the United Kingdom. The goal of the game is to protect the people of the United Kingdom from floods that damage the economy and lives of the people through an assortment of realistic means over a time span of three years.' FROM games WHERE igdb_id = 172689 ON CONFLICT (game_id, language_code) DO NOTHING;
