INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Majin Tensei: Blind Thinker II', 'Despite the title, while the mechanics of Blind Thinker II remain the same as they were in Majin Tensei: Blind Thinker, the setting, story, and characters have all changed. The protagonist of this chapter is called Takeru and much of the story centers around an artificially created demon called Zora. Player choices in the game lead to multiple potential endings.' FROM games WHERE igdb_id = 129140 ON CONFLICT (game_id, language_code) DO NOTHING;
