INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('arcana-heart-2', 15865, '2008-03-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6blz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclttn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcana Heart 2', 'Arcana Heart 2 is the sequel to Arcana Heart. It was the first game in the series to be developed and published by Examu after the rights of the franchise had been transferred to the company from Yuki Enterprise. It was also the first game for Examu''s proprietary eX-Board, an arcade board based on Windows XP Embedded that would become the standard platform for the rest of the series and other arcade games published by Examu. The game was unveiled at the AOU2008 Amusement Expo. Andamiro demonstrated the original version of Arcana Heart 2 in the US at the 2008 Amusement Expo conference from September 10 to September 12, 2008. The game was running in a Japanese "candy" cabinet but with English gameplay and artwork. It was released in the US in October 2008 as a conversion kit to change other arcade games into an Arcana Heart 2 arcade game.
