INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('funfair-party--1', 159042, '2008-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gkq.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Funfair Party', 'Funfair Party assembles a variety of 23 funfair themed minigames for the Nintendo Wii. From simple target shooting to memory and reflex games inside or outside the circus tent, Funfair Party provides hours of fun and challenge for every member of the family. Featuring two distinct play modes, players can choose to immerse themselves in a heroic narrative where the success of each minigame helps a young boy stave-off a looming threat to the funfair, or, for a quicker play experience, pick-and-choose their favourite minigames to play with a friend. Funfair Party takes full advantage of the unique Wii Remote controller with a variety of gestural commands, custom-designed for each game.' FROM games WHERE igdb_id = 159042 ON CONFLICT (game_id, language_code) DO NOTHING;
