INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'L the Prologue to Death Note -Spiraling Trap-', 'L the Prologue to Death Note -Spiraling Trap- was released for the Nintendo DS in Japan on February 7, 2008. The player assumes the role of a rookie FBI agent who awakens in a strange hotel and attempts to escape with the help of L, who provides assistance via an in-game PDA. The story is set before the Kira investigation in the original series.' FROM games WHERE igdb_id = 22390 ON CONFLICT (game_id, language_code) DO NOTHING;
