INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Protoganda II', 'Protoganda II is a shoot ''em up game and a sequel to Protoganda: Strings, with retro-styled graphics. The player controls a small spaceship which faces a number of powerful battleships, one by one. Each enemy ship keeps rapidly changing its shape and rearranging its elements, all while firing relentlessly. The player must shoot off parts of the enemy ship while avoiding enemy gunfire and flying debris.' FROM games WHERE igdb_id = 199153 ON CONFLICT (game_id, language_code) DO NOTHING;
