INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art Style: Base 10', 'Art Style: Base 10 is a puzzle game developed by Skip Ltd. and released for the Nintendo DSi in 2010 as part of the *Art Style* series. Players guide falling blocks into a grid where values combine according to a base-10 system. When numbers add up to ten, they disappear from the board and award points. The game focuses on simple mechanics, gradual difficulty, and a minimalist visual presentation' FROM games WHERE igdb_id = 84764 ON CONFLICT (game_id, language_code) DO NOTHING;
