INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Petz Rescue: Wildlife Vet', 'Play as a young vet, who has just opened their first animal clinic. Take care of your neighbors’ domesticated pets, as well as the local exotic baby animals. Diagnose, cure, observe and heal the animals to gain your clients’ confidence and respect. Uncover the mystery behind the animals’ illnesses. Investigate to find out if the local factory could be polluting the rivers and thus be causing the animals’ diseases. Face real challenges on the journey to becoming a great veterinarian, and possibly join one of the world’s most prestigious NGOs.' FROM games WHERE igdb_id = 47918 ON CONFLICT (game_id, language_code) DO NOTHING;
