INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('heise-biji', 330272, '2008-03-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9d33.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv8r0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heise Biji', 'This story is about when the "the seekers of the way" confront the many complexities facing the end of the world, where there is no distinction between absolute good and evil, they rely on the values of their own beliefs to choose a path that suits their will. Possibly, it can also be said that the game''s protagonist, a "saint" who came to this world from the ocean, symbolizes the "cradle of life" and death''s final destination. He accepts these destined, indefinite calamitous trials to understand the truth of "life and will", thus venturing on the never-ending journey of no return to become a transcendent... The content of the work attempts to explore includes: "environmental crises", "religious conflicts", "a return to nature", "the awakening of the ego", "totem banquets", and so on.' FROM games WHERE igdb_id = 330272 ON CONFLICT (game_id, language_code) DO NOTHING;
