INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi no Kira-kira Omisecchi', 'Tamagotchi no Kira-kira Omisecchi is a Japan-only Nintendo DS entry in the Tamagotchi Corner Shop spin-off series. Set in the town of Celebria, players work with Tamagotchi characters such as Mametchi, Memetchi, Kuchipatchi, and Violetchi to run and expand various shops through mini-games, including clothing design, jewelry making, fireworks shows, and a McDonald’s collaboration. Shops can be upgraded to Royal status, and a special “My Brand” boutique allows players to create custom dresses. The game also includes tower customization and over 100 Tamagotchi characters to interact with.' FROM games WHERE igdb_id = 77625 ON CONFLICT (game_id, language_code) DO NOTHING;
