INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meritous', 'Meritous is an independently-made PC game, a cross between a top-view dungeon crawler and a bullet-hell shoot-em-up. In it, you control main character Merit, who travels through an enormous 3000-room labyrinth, the Orcus Dome, in order to find three artifacts called the PSI Keys, and restore them to their proper locations. 
