INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atlantica Online', 'Atlantica Online is a turn-based tactical MMORPG in which the player primarily assumes the role of a descendant of the Atlantean people. The primary goal of the game is to search for your ancestral home to save the world from the effects of Oriharukon, a substance created by the ancient Atlanteans. To accomplish this goal, the player must embark upon a journey spanning the globe and transcending time in search of clues that will lead to the lost civilization, battling men, monsters, and machines along the way that have been corrupted by the Oriharukon’s Influence.' FROM games WHERE igdb_id = 9522 ON CONFLICT (game_id, language_code) DO NOTHING;
