INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumpin'' Jack', 'Help Jack rescue his family from the demons of the underworld in this power-packed run ''n'' jump adventure. Collect thousands of coins, wipe out countless enemies, and utilize an assortment of wild acrobatic contraptions to reach the exit at the end of each level. Jumpin` Jack features stunning side-scrolling worlds packed with vibrant detail and a heartwarming story. If you loved the classic platform games of yesteryear, then you can''t help but gush over Jumpin'' Jack.' FROM games WHERE igdb_id = 331068 ON CONFLICT (game_id, language_code) DO NOTHING;
