INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avernum 5', 'Avernum is one of the great tales of indie gaming, an epic series of fantasy role-playing adventurers set in an enormous, subterranean nation. Avernum is a land underground, a subterranean nation full of rogues, misfits, and brigands, struggling for survival and wealth in the monster-infested darkness. Avernum 5 is the second chapter in the Great Trials Trilogy, three games that tell the tale of this land’s struggles in the face of powerful forces that seek to destroy it.' FROM games WHERE igdb_id = 16338 ON CONFLICT (game_id, language_code) DO NOTHING;
