INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortimer Beckett and the Time Paradox', 'Mortimer Beckett''s back for an all-new, eye-popping adventure! Although Mortimer was able to get rid of the ghosts in his last outing, his Uncle Jerome''s home is now host to another ominous challenge - a time portal! Even worse, the Time Bomb that Jerome built to close the portal has been scattered across eight different eras! Join Mortimer for a wild trip to find the scattered Time Bomb, put it back together, and close the portal before it''s too late!' FROM games WHERE igdb_id = 8327 ON CONFLICT (game_id, language_code) DO NOTHING;
