INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Actionauts', 'In 1984, Rob Fulop began work on what would be his last game for the Atari 2600, a ''robot programming'' game entitled "Actionauts". Due to the market conditions for Atari 2600 cartridges at the time, Actionauts was never completed, and was not shown or released to the gaming public until 2008. The original, seemingly simple puzzle-game challenges a single player to use the program editor to construct a sequence of commands to navigate an onscreen robot to reach the ''cheese''. It''s not nearly as easy as it looks!' FROM games WHERE igdb_id = 40658 ON CONFLICT (game_id, language_code) DO NOTHING;
