INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scoops', 'From the maker of the popular free puzzle game Hanoi, Scoops puts you in control of a towering stack of ice cream scoops! Stack your cone high into the sky by tilting the phone left and right, catching as many scoops as you can while avoiding the vegetables (veggies are great separate from ice cream!). The higher you go, the faster they fall, and the more wobbly your tower! Stack similar colors together for extra points. Can you stack your cone to the MOON? Throw on some tunes in iPod, and start stacking!' FROM games WHERE igdb_id = 232584 ON CONFLICT (game_id, language_code) DO NOTHING;
