INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kid Paddle: Lost in the Game', 'Kid Paddle: Lost in the Game is a 3D platform game inspired by Midam''s comic strip Kid Paddle. Kid Paddle and his friends go play games at the City Game Arcade, but things turn sour when they become trapped inside the game and Kid Paddle''s friends are being held captive by the evil blorks. Kid Paddle must journey through four different worlds to save his friends by activating switches, jumping on platforms and fighting many different blorks. It''s also possible to play as Little Barbarian and save the princess in two of the game''s six worlds.' FROM games WHERE igdb_id = 268186 ON CONFLICT (game_id, language_code) DO NOTHING;
