INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Word Safari: The Friendship Totems', 'Word Safari combines the best of adventure video gaming with true learning content. To save the tribes of the Serengeti, you must journey across deserts and raging rivers, through thick jungles and hidden temples. You''ll need to befriend the animals of Africa and use all your reading, spelling, and language skills to become The Chosen One and save the Sacred Watering Hole.' FROM games WHERE igdb_id = 49472 ON CONFLICT (game_id, language_code) DO NOTHING;
