INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Antbuster', 'Antbuster is a game that aims to protect your delicious cake on a picnic. The cake has 8 pieces and the ants will do everything to reach them. Fortunately, you can spread cannons through the garden, and each cannon can be evolved in several different ways. There are over 50 different types of cannons to crush these insects. Can you protect the picnic?' FROM games WHERE igdb_id = 242158 ON CONFLICT (game_id, language_code) DO NOTHING;
