INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hula Wii: Hula de Hajimeru - Bi to Kenkou!', 'In Hula Wii: Hula de Hajimeru - Bi to Kenkou! by utilizing the Wii Balance Board, players can take Hula lessons right in front of the television and learn how to shake, gesticulate, and dance like a native Hawaiian. In addition to the tutorials, the software also includes footage of dancers doing the Hula in the classic style. A video travelogue developed with the participation of the Hawaii Tourism Authority is also included on the Wii DVD which shows off the sights and natural beauty of Hawaii.' FROM games WHERE igdb_id = 141473 ON CONFLICT (game_id, language_code) DO NOTHING;
