INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diner Dash: Flo Through Time', 'Dash through history in this timeless and challenging Diner Dash sequel. When Grandma Florence converts Flo''s microwave into a time machine, Flo and Grandma are instantly zapped into the distant past. Help them earn their way back, as they sling historic hash to make cash in 5 all-new restaurants. Bring out your primal waitress at the Caveman Café, serve up some chivalry at the All Knight Diner, and join the sky-high futuristic fun-fest at the Snack to the Future Diner!' FROM games WHERE igdb_id = 141919 ON CONFLICT (game_id, language_code) DO NOTHING;
