INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boombot', 'Boombot is a physics-based puzzle game where players are tasked with guiding the titular character through diverse levels using explosives. The game requires players to strategically position and explode bombs to propel Boombot towards the exit, all the while steering clear of obstacles and pitfalls.' FROM games WHERE igdb_id = 275180 ON CONFLICT (game_id, language_code) DO NOTHING;
