INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble Bloomers', 'Hiroki loves bloomers and now works hard for preparation for sports day. Runa, who gets sexually excited when wearing bloomers, and Saki, who suddenly tells Hiroki that she loves him. Well, which girl (bloomers) will Hiroki choose...?' FROM games WHERE igdb_id = 127962 ON CONFLICT (game_id, language_code) DO NOTHING;
