INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DT Carnage', 'In DT Carnage, drivers must be prepared to bring everything they''ve got onto the tracks as they find themselves racing for their reputation, honor, and ultimately, their lives. Relying on speed alone is no longer enough as explosives and weapons are used on a regular basis making violence the ultimate means to an end in the underground racing world. Still think you have what it takes to be a DT racer?' FROM games WHERE igdb_id = 42750 ON CONFLICT (game_id, language_code) DO NOTHING;
