INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AliveZ', 'Fifteen years ago, a mysterious shrine suddenly appeared. It emitted an evil air and people were transformed one after another.... Yin, a group of evil people, and Yang, a group of people who has an opposite nature to Yin. The story takes place in the midst of slaughter happened in the town....' FROM games WHERE igdb_id = 327925 ON CONFLICT (game_id, language_code) DO NOTHING;
