INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Yakyuu Spirits 5 Kanzenban', 'An updated version of Pro Yakyū Spirits 5 with many improvements over the original as a post-season version of the game. For instance, every player who appeared in a game in the 2008 NPB season for all 12 teams was included on each team''s roster, there were new player animations, enhanced artificial intelligence, and also small improvements to graphics (foreign players, for example, no longer look generic and have their actual swings), online play, baserunning, and fielding.' FROM games WHERE igdb_id = 92236 ON CONFLICT (game_id, language_code) DO NOTHING;
