INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Horse & Me: Riding for Gold', 'Packed with exciting new features, brand new graphics and animations, and an engrossing storyline, horse sports fans will be treated to the most complete equestrian experience and the most realistic horse simulation ever seen in a game. My Horse and Me: Riding for Gold will let players live the ultimate bond between them and their horse. The My Horse and Me series boasts the exclusive worldwide license from the Fédération Equestre Internationale (FEI), the world''s leading horse sports organization.' FROM games WHERE igdb_id = 50656 ON CONFLICT (game_id, language_code) DO NOTHING;
