INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zero no Tsukaima: Maigo no Period to Ikusen no Symphony', 'The story is a separate continuation from the anime and follows the adventures of Saito and Louise when they are tasked with checking out a library after reports of ghosts inhabiting it arise. During the search Louise goes missing, and when they find her Saito and crew discover Louise has lost her memory. The librarian tells them they will need to go into the various books in the library to recover Louise''s memory. Saito and friend''s adventure into the world of the books then begins. Notable changes from the other entries in the series include the "tsundere meter" being reworked from a notched bar to a gradient circle gauge, while also lacking the turn based combat sections from the first entry.' FROM games WHERE igdb_id = 268804 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 268804 AND p.igdb_id = 8 ON CONFLICT DO NOTHING;
