INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Baseball ''09', 'Play hardball with David "Big Papi" Ortiz, A-Rod, Jeter, Ichiro, Griffey, Pujols, and other MLB superstars as kids. Choose your favorite MLB or Backyard team or create your own. And now, for the first time on Wii, Backyard Baseball 2009 features NEW Backyard Baseball All Star Game and tournament mode along with season & single game options, create-a-player, Homerun Derby mini-game, and unlockables. With outrageous game play and awesome power ups combined with authentic baseball action, Backyard Baseball 09 is the most fun you can have outside the ball park.' FROM games WHERE igdb_id = 132055 ON CONFLICT (game_id, language_code) DO NOTHING;
