INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life is a Race', 'Life is a Race is a simple game which metaphorically depicts the human life as a course to be run as fast as possible. The player must click the left mouse button rapidly to make the on-screen character rush forward while moving through all the life stages. The goal of the game is to get as low a time as possible.' FROM games WHERE igdb_id = 199086 ON CONFLICT (game_id, language_code) DO NOTHING;
