INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taiko no Tatsujin 11', 'A sequel to Taiko no Tatsujin 10, this new title tried to enhance the quality of life for the users by adding the Ura Oni difficulty for the expert players and the Papa Mama Support mode for the young players, it also added the ability to change the sound of the Taiko which already was a thing in the console games, and they removed the Revival Roulette to replace it with the Revival Drumroll minigame.' FROM games WHERE igdb_id = 276422 ON CONFLICT (game_id, language_code) DO NOTHING;
