INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bobby Carrot 4: Flower Power', 'At last – Bobby Carrot is back! This time our clever hare has a whole swarm of butterflies in his tummy. He wants to plant beautiful flowers for his girlfriend. But the best soil can only be found in the tricky garden of riddles. Help Bobby to put his plan into action and escort him through 60 fiddly garden levels. The fantastic forth installment of the series featuring tons of riddles, traps, gags and new bonus features!' FROM games WHERE igdb_id = 135939 ON CONFLICT (game_id, language_code) DO NOTHING;
