INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure: The Inside Job', 'Thalia James, member of the Earth Anti-Encroachment League for over twenty years, has contracted a bizarre disorder during an inspection of a distant planet. Now it seems that danger is always two steps behind her as she continues what she once considered a relatively mundane job. It seems as if there is something rotten in the state of the Milky Way...' FROM games WHERE igdb_id = 60796 ON CONFLICT (game_id, language_code) DO NOTHING;
