INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akko de Pon! Ikasama Hourouki', 'Akko de Pon! Ikasama Hourouki is a mahjong game that aims to win by making full use of Ikasama skills. It''s possible to use the Wii Remote to control tricks that only mahjong lovers know, such as “bukkake pulling out”, “swallowing back”, “elevator”, etc. Enjoy thrilling Ikasama mahjong that you can''t taste in traditional mahjong games! It is possible to play normal mahjong that can''t use squid skills.' FROM games WHERE igdb_id = 65280 ON CONFLICT (game_id, language_code) DO NOTHING;
