INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghajini: The Game', 'Ghajini: The Game is a third-person action game based on the 2008 film Ghajini. It was published in 2008 by FXLabs and Geetha Arts, and distributed by Eros Home Entertainment. It was hailed as India''s first true 3D PC game. The game consists of five levels, following the story of the protagonist, Sanjay Singhania (portrayed by Aamir Khan), avenging the death of his girlfriend Kalpana by using martial arts, various weapons, and other artifacts.' FROM games WHERE igdb_id = 215001 ON CONFLICT (game_id, language_code) DO NOTHING;
