INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luntik Learns Letters', 'Our favorite character, as well as the favorite of many modern children, Luntik, invites all young children to go with him on an exciting journey, during which he will conduct very unusual reading lessons. If your child thinks that memorizing letters is a rather boring activity, then this game will definitely change his opinion by turning learning into an exciting game. General Sher, Little Bee, Kuzya and Mila will help Luntik teach your children to read.' FROM games WHERE igdb_id = 268373 ON CONFLICT (game_id, language_code) DO NOTHING;
