INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Settlers: Rise of Cultures', 'Olympus had it enough with those stupid humans and doesn''t want them to use his name for anything anymore. But his two counsel angles convince him to give the humans a last chance to regain his respect. So now the Bavarians, Scots and Egyptians need to complete some objectives for Olympus while an evil Bavarian General and the Goddess Sachmet try to sabotage their doings.' FROM games WHERE igdb_id = 132810 ON CONFLICT (game_id, language_code) DO NOTHING;
