INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamen Rider Battle: Ganbaride', 'Kamen Rider Battle: Ganbaride is a combination of an arcade game and a collectible item game featuring the protagonists of the Kamen Rider Series. The game is being released as part of the 10th anniversary of the Heisei run Kamen Rider Series by Toei, TV Asahi & Ishimori Productions and features heavy tie-ins with the television series Kamen Rider Decade, whose protagonists use cards similar to those used in the game. It is played in a similar fashion to Sega''s Mushiking and Dinosaur King games, and uses special Data Cardass cards released by Bandai.' FROM games WHERE igdb_id = 83930 ON CONFLICT (game_id, language_code) DO NOTHING;
