INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stick Ranger', 'In the game, the player controls four characters with the mouse by dragging them. These characters wander about automatically, defeating enemies they encounter and passing through levels to reach bosses. The levels are all optional (the player can simply drag a character to the next sign to skip levels), but to unlock the following stage the player has to kill the boss at the end of each stage.' FROM games WHERE igdb_id = 57898 ON CONFLICT (game_id, language_code) DO NOTHING;
