INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Windchaser', '“Windchaser” combines an innovative genre mix of 3-D real-time tactics, a story based campaign, many fantasy role-playing elements and a pinch of strategy in the shape of a mobile headquarters. Together with the crew of an air-sailing ship, the player resorts to sword and magic to fight human opponents and battle an ancient, resurrected evil power. Only our hero Ioan with his spirited girlfriend Shara and an old soldier called Caine, can save the fantasy world Ensai from the upcoming apocalypse.' FROM games WHERE igdb_id = 50435 ON CONFLICT (game_id, language_code) DO NOTHING;
